// A function to sort a vector of integers using bubble sort
fn bubble_sort(mut v: Vec<i32>) -> Vec<i32> {
    // Get the length of the vector
    let n = v.len();
    // Loop over the vector n-1 times
    for i in 0..n-1 {
        // Loop over the unsorted part of the vector
        for j in 0..n-i-1 {
            // If the current element is larger than the next one, swap them
            if v[j] > v[j+1] {
                v.swap(j, j+1);
            }
        }
    }
    // Return the sorted vector
    v
}

